export const MONUMENTS = JSON.parse("[{\"id\":\"n1882615028\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"В. А. Жуковский\",\"x\":-2216.7,\"z\":-584.9,\"startDate\":\"1887\",\"subject\":\"Q157623\"},{\"id\":\"n3842754772\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Флора Фарнезская\",\"x\":-2206.9,\"z\":-654.8,\"startDate\":\"1833\",\"artist\":\"Шарлемань Л.И.\"},{\"id\":\"n6077101809\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. К. Григоровичу\",\"x\":-2251.1,\"z\":-650.8,\"subject\":\"Q936152\",\"inscription\":\"В этом здании в 1909-1917 годах работал видный деятель Российского флота, последний морской министр Российской Империи, генерал-адъютант, адмирал Иван Константинович Григорович (1853-1930)\"},{\"id\":\"n1882585055\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"М. Ю. Лермонтов\",\"x\":-2316.4,\"z\":-508,\"wikidata\":\"Q25395463\",\"wikipedia\":\"ru:Памятник Лермонтову (Санкт-Петербург, Александровский сад)\"},{\"id\":\"n4898059105\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. Адамсу\",\"x\":-2296.5,\"z\":83.7,\"subject\":\"Q11816\",\"inscription\":\"Здесь в 1810-1811 годах жил первый посланник США в России Джон Квинси Адамс шестой президент Соединённых Штатов Америки\"},{\"id\":\"n9016104791\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-2311.4,\"z\":134.8,\"subject\":\"Q1394\",\"inscription\":\"В этом здании в декабре 1917 г. В.И. Ленин участвовал в заседании Бюро Высшего Совета Народного Хозяйства, на котором обсуждался подготовленный им \\\"Проект Декрета о проведении в жизнь национализации банков и о необходимых в связи с этим мерах\\\"\"},{\"id\":\"n4436516900\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-2146.6,\"z\":-494.1,\"subject\":\"Q1394\",\"inscription\":\"В этом доме на собрании военной организации петроградского комитета и членов ЦК РСДРП(б) 13 апреля 1917 года В.И. Ленин выступил с речью о содержании и методах агитации среди солдат\"},{\"id\":\"n4683728159\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. И. Багратиону\",\"x\":-2101,\"z\":-218.7,\"subject\":\"Q239260\",\"inscription\":\"В этом доме с 1801 по 1803 год жил герой Отечественной войны 1812 года князь Пётр Иванович Багратион (1765-1812)\"},{\"id\":\"n4683728164\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. В. Гоголю\",\"x\":-2268.6,\"z\":-285.8,\"subject\":\"Q43718\",\"inscription\":\"В этом доме с 1833 г. по 1836 г. жил Николай Васильевич Гоголь\"},{\"id\":\"n4683728165\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. К. Блюхеру\",\"x\":-2178.6,\"z\":-351,\"subject\":\"Q48129\",\"inscription\":\"В этом доме с 1923 по 1926 год жил выдающийся советский полководец, Маршал Советского Союза Василий Константинович Блюхер\"},{\"id\":\"n4683728166\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. С. Улановой\",\"x\":-2191.1,\"z\":-341.9,\"subject\":\"Q28885\",\"inscription\":\"В этом доме с 1926 по 1935 год жила великая русская балерина Галина Сергеевна Уланова\"},{\"id\":\"n4683728167\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. И. Чайковскому\",\"x\":-2188.9,\"z\":-343.6,\"subject\":\"Q7315\",\"inscription\":\"Пётр Ильич Чайковский родился 25-го апреля 1840-го года в Вятской губернии на Воткинском заводе. Скончался в этом доме 25-го октября 1893-го года\"},{\"id\":\"n5854740072\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. Э. Дзержинскому\",\"x\":-2277.2,\"z\":-438,\"subject\":\"Q188570\",\"inscription\":\"В этом доме с 7 (20) декабря 1917 года по 10 (23) марта 1918 года находилась Всероссийская Чрезвычайная Комиссия по борьбе с контрреволюцией и саботажем, которую возглавлял [...] Феликс Эдмундович Дзержинский\",\"description\":\"Из-за ограничений на длину текста пропущен следующий фрагмент: \\\"выдающийся деятель Коммунистической партии и Советского государства, ближайший соратник В.И. Ленина\\\"\"},{\"id\":\"n5854766833\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. О. Дунаевскому\",\"x\":-2257.7,\"z\":-412.2,\"subject\":\"Q638638\",\"inscription\":\"В этом доме с 1936 по 1941 год жил и работал выдающийся композитор Исаак Осипович Дунаевский\"},{\"id\":\"n5854766836\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Я. Вагановой\",\"x\":-2250.7,\"z\":-402.8,\"subject\":\"Q236413\",\"inscription\":\"Здесь с 1937 года по 1951 год жила Агриппина Яковлевна Ваганова, профессор, крупнейший деятель советской хореографии\"},{\"id\":\"n5854766837\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. П. Преображенской\",\"x\":-2249.2,\"z\":-400.8,\"subject\":\"Q4377282\",\"inscription\":\"В этом доме с 1937 по 1966 год жила народная артистка СССР, лауреат Государственных премий СССР, профессор Софья Петровна Преображенская\"},{\"id\":\"n5854766838\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. В. Ершову\",\"x\":-2253.3,\"z\":-406.3,\"subject\":\"Q4176892\",\"inscription\":\"В этом доме с 1931 по 1941 год жил великий русский певец, профессор Ленинградской консерватории, народный артист СССР Иван Васильевич Ершов\"},{\"id\":\"n5854766842\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. А. Алиеву\",\"x\":-2229.9,\"z\":-375.5,\"subject\":\"Q157451\",\"inscription\":\"В этом доме, в Высшей школе МГБ СССР в 1949-1950 гг. учился выдающийся государственный деятель, президент Азербайджанской республики Гейдар Алиевич Алиев\"},{\"id\":\"n6424179538\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. К. Рериху\",\"x\":-2238.4,\"z\":-85.2,\"subject\":\"Q208993\",\"inscription\":\"В этом доме с 1906 по 1917 год жил и работал Николай Константинович Рерих, русский художник, археолог и путешественник\"},{\"id\":\"n6433994500\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Андрееву\",\"x\":-2196.1,\"z\":44.6,\"subject\":\"Q982300\",\"inscription\":\"Здесь с 1912 по 1918 гг жил и работал основатель оркестра русских народных инструментов Василий Васильевич Андреев\"},{\"id\":\"n6481181510\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2166.1,\"z\":-331.4,\"startDate\":\"2018-10-04\",\"inscription\":\"В этом здании с 01.12.1917 по 15.07.1918 располагалось Петроградское столичное управление уголовного розыска\"},{\"id\":\"n6591379413\",\"kind\":\"memorial\",\"sub\":\"sculpture\",\"name\":\"Открытию регулярного трамвайного движения в Санкт-Петербурге\",\"x\":-2289.4,\"z\":-479.6,\"inscription\":\"Здесь проходила первая линия петербургского трамвая «Главный Штаб — 8-я линия В.О.», открыта 29 (16) октября 1907 года\",\"wikidata\":\"Q4205022\",\"wikipedia\":\"ru:История санкт-петербургского трамвая\"},{\"id\":\"n13243952901\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2216.1,\"z\":248.8}]");
